#include "txn/workload.h"
#include <iostream>
#include <string>
using namespace rrl;
int main(int argc,char** argv){WorkloadConfig c;std::string index_name="v2";for(int i=1;i+1<argc;i+=2){std::string o=argv[i],v=argv[i+1];if(o=="--workload")c.kind=WorkloadTrace::parse_kind(v);else if(o=="--index")index_name=v;else if(o=="--keys")c.key_count=std::stoull(v);else if(o=="--txns")c.transaction_count=std::stoull(v);else if(o=="--ops")c.operations_per_transaction=std::stoull(v);else if(o=="--range")c.range_length=std::stoull(v);else if(o=="--threads")c.threads=std::stoull(v);else if(o=="--seed")c.seed=std::stoull(v);else if(o=="--zipf")c.zipf_theta=std::stod(v);else if(o=="--items")c.tpcc_items_per_order=std::stoull(v);}auto trace=WorkloadTrace::generate(c);BTreeSingle v1;BTreeLatch v2;BTreeIndex* index=nullptr;if(index_name=="v1"){v1.init(128);index=&v1;c.threads=1;}else{v2.init(128);index=&v2;}auto s=run_workload(*index,trace,c.threads);std::cout<<"workload="<<WorkloadTrace::name(c.kind)<<",index="<<index_name<<",threads="<<c.threads<<",transactions="<<s.transactions<<",operations="<<s.operations<<",reads="<<s.reads<<",updates="<<s.updates<<",inserts="<<s.inserts<<",range_reads="<<s.range_reads<<",rows_found="<<s.rows_found<<",rows_scanned="<<s.rows_scanned<<",throughput_txn_s="<<s.throughput()<<",checksum="<<s.checksum<<"\n";return 0;}